export const projetos=[{titulo:"Arrecadação de alimentos",descricao:"Arrecadamos alimentos para ajudar famílias em situação de vulnerabilidade.",imagem:"../imagens/Doacoes.png",tipo:"Projeto ativo"},{titulo:"Ações voluntárias",descricao:"Voluntários participam de ações sociais para ajudar nossa comunidade.",imagem:"../imagens/Voluntarios.png",tipo:"Voluntariado"}];export function criarCardProjeto(a){return`\n        <div class="card-projeto">\n            <img src="${a.imagem}" alt="${a.titulo}">\n            \n            <div class="card-conteudo">\n                <span class="tipo-projeto">${a.tipo}</span>\n                \n                <h3>${a.titulo}</h3>\n                \n                <p>${a.descricao}</p>\n                \n                <button onclick="abrirModal()">\n                    Saiba mais\n                </button>\n            </div>\n        </div>\n    `}